using System;
using System.Collections.Generic;
using System.Diagnostics;

// PROGRAM: Menguji Kecepatan Pencarian: List (O(N)) vs HashSet (O(1))
const int TotalData = 100_000;
var list = new List<string>(TotalData);
var set = new HashSet<string>(TotalData);

for (int i = 0; i < TotalData; i++)
{
    string id = $"USER_{i:D6}";
    list.Add(id);
    set.Add(id);
}

string targetId = "USER_099999"; // Elemen paling ujung akhir

// 1. Pencarian di List (Linear Scan O(N))
var swList = Stopwatch.StartNew();
bool foundList = false;
for (int r = 0; r < 500; r++)
{
    foundList = list.Contains(targetId);
}
swList.Stop();
Console.WriteLine($"List.Contains (500x Lookup): {swList.ElapsedMilliseconds} ms (Found: {foundList})");

// 2. Pencarian di HashSet (Hash Lookup O(1))
var swSet = Stopwatch.StartNew();
bool foundSet = false;
for (int r = 0; r < 500; r++)
{
    foundSet = set.Contains(targetId);
}
swSet.Stop();
Console.WriteLine($"HashSet.Contains (500x Lookup): {swSet.ElapsedMilliseconds} ms (Found: {foundSet})");

