using System;
using System.Collections.Generic;
using System.Linq;

public class TokenDeduplicator
{
    public static string[] GetUniqueSortedTokens(string?[] tokens)
    {
        if (tokens == null || tokens.Length == 0) return Array.Empty<string>();

        var uniqueSet = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

        foreach (var t in tokens)
        {
            if (string.IsNullOrWhiteSpace(t)) continue;
            uniqueSet.Add(t.Trim().ToUpperInvariant());
        }

        var list = uniqueSet.ToList();
        list.Sort(StringComparer.Ordinal);
        return list.ToArray();
    }

    public static void Main()
    {
        string?[] data = { "tok-a", " TOK-B ", "tok-a", null, "tok-c" };
        var hasil = GetUniqueSortedTokens(data);
        Console.WriteLine(string.Join(", ", hasil));
    }
}
